$ErrorActionPreference='Stop';$ProgressPreference='SilentlyContinue'
if(@(Get-Process swift,swiftc,swift-build,clang,FactoryProbe -ErrorAction SilentlyContinue).Count){throw 'compiler/native lane busy'}
$Root='D:\Claude\swiftright\.factory-work\runtime-stage\api-image-body-r1'
if(Test-Path -LiteralPath $Root){throw 'fresh runtime source namespace required'}
New-Item -ItemType Directory -Path $Root|Out-Null
$Zip=Join-Path $Root 'source.zip';$Runtime=Join-Path $Root 'runtime';$Scratch=Join-Path $Root 'scratch'
[IO.File]::WriteAllBytes($Zip,[Convert]::FromBase64String(''))
if((Get-FileHash -LiteralPath $Zip).Hash.ToLowerInvariant() -cne '441ffb72fdede84906760ac8ee9f3fa918479cccb0b8f705584578d6e2f3a6f9'){throw 'runtime zip hash drift'}
Add-Type -AssemblyName System.IO.Compression.FileSystem
[IO.Compression.ZipFile]::ExtractToDirectory($Zip,$Runtime)
$Rows=[Text.Encoding]::UTF8.GetString([Convert]::FromBase64String(''))|ConvertFrom-Json
foreach($Row in $Rows){$P=Join-Path $Runtime $Row.path;if((Get-Item -LiteralPath $P).Length -ne $Row.bytes -or (Get-FileHash -LiteralPath $P).Hash.ToLowerInvariant() -cne $Row.sha256){throw ('runtime source drift: '+$Row.path)}}
if(@(Get-ChildItem -LiteralPath $Runtime -File -Recurse).Count -ne $Rows.Count){throw 'extra runtime source files'}
& swift.exe test --package-path $Runtime --scratch-path $Scratch --jobs 1 -Xswiftc -j1 -Xswiftc -num-threads -Xswiftc 1
$Result=$LASTEXITCODE;if($null -eq $Result){throw 'Swift exit code missing'};exit ([int]$Result)
